from datetime import datetime
from .interface import DefaultRMODInterface
from .connectors import SerialConnector, NetworkConnector
from .session_logger import RMODSessionLogger
from ..exceptions import UnknownConnectorTypeError


class RMODBuilder:
    default_rmod_interface = DefaultRMODInterface
    connector_lookup = {
        'SERIAL': SerialConnector,
        'NETWORK': NetworkConnector
    }
    logger = RMODSessionLogger

    @staticmethod
    def build(login, password, port, log_dir):
        connector = RMODBuilder._get_connector_for_port(port)
        logger, log_path = RMODBuilder._build_rmod_session_logger(port, log_dir)
        rmod = RMODBuilder.default_rmod_interface(connector(port), logger)
        rmod.set_credentials(login, password)
        return rmod, log_path

    @staticmethod
    def _build_rmod_session_logger(port, log_dir):
        logger_name = f"{port.split('/')[-1]}_{datetime.now().strftime('%y.%m.%d_%H-%M-%S')}"
        log_path = log_dir / f"{logger_name}.log"
        return RMODBuilder.logger(name=logger_name, log_path=log_path), log_path

    @staticmethod
    def _get_connector_for_port(port):
        connector_type = 'NETWORK' if ':' in port else 'SERIAL'
        connector = RMODBuilder.connector_lookup.get(connector_type.upper(), None)
        if connector is None:
            raise UnknownConnectorTypeError(f"Currently supported types: {RMODBuilder.connector_lookup.keys()}")
        return connector

    @staticmethod
    def build_custom(port, log_dir, login, password, shell_prompt_regex=None):
        connector = RMODBuilder._get_connector_for_port(port)
        logger, log_path = RMODBuilder._build_rmod_session_logger(port, log_dir)
        rmod = RMODBuilder.default_rmod_interface(connector(port), logger)
        rmod.set_credentials(login, password)
        if shell_prompt_regex:
            rmod.shell_prompt_regex = shell_prompt_regex
        rmod.is_sudo_needed = login != 'root'
        return rmod, log_path
